def transform(grid):
    h, w = len(grid), len(grid[0])
    # The colored object is a stencil: copy its shape onto every all-zero
    # placement in the background, retaining the stencil's color.
    color = None
    cells = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (0, 9):
                color = grid[r][c]
                cells.append((r, c))
    if color is None:
        return [row[:] for row in grid]
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    shape = [(r-r0, c-c0) for r, c in cells]
    sh, sw = max(r for r, c in shape)+1, max(c for r, c in shape)+1
    out = [row[:] for row in grid]
    for r in range(h-sh+1):
        for c in range(w-sw+1):
            if all(grid[r+dr][c+dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[r+dr][c+dc] = color
    return out
